import { db } from '../client';
import { users } from '../schema';
import { eq } from 'drizzle-orm';

export async function findUserByPhone(phone: string) {
  return db.select({ id: users.id, phone: users.phone })
    .from(users)
    .where(eq(users.phone, phone));
}

